CREATE TABLE activity_coach(id UUID PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES identity_tenant(id),display_name VARCHAR(180) NOT NULL,phone VARCHAR(40),email VARCHAR(254),specialty VARCHAR(180),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE activity(id UUID PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES identity_tenant(id),code VARCHAR(60) NOT NULL,name VARCHAR(180) NOT NULL,category VARCHAR(30) NOT NULL,description VARCHAR(1000),coach_id UUID REFERENCES activity_coach(id),allow_parent_enrollment BOOLEAN NOT NULL DEFAULT FALSE,price NUMERIC(14,2) NOT NULL DEFAULT 0,currency_code VARCHAR(3) NOT NULL DEFAULT 'MAD',status VARCHAR(20) NOT NULL DEFAULT 'OPEN',created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT uq_activity_code UNIQUE(tenant_id,code),CONSTRAINT ck_activity_category CHECK(category IN('SPORT','SWIMMING','ROBOTICS','MUSIC','DAYCARE','OTHER')),CONSTRAINT ck_activity_status CHECK(status IN('DRAFT','OPEN','CLOSED','ARCHIVED')),CONSTRAINT ck_activity_price CHECK(price>=0));
CREATE TABLE activity_capacity(id UUID PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES identity_tenant(id),activity_id UUID NOT NULL REFERENCES activity(id),maximum_enrollments INTEGER NOT NULL,waiting_list_enabled BOOLEAN NOT NULL DEFAULT TRUE,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT uq_activity_capacity UNIQUE(tenant_id,activity_id),CONSTRAINT ck_activity_capacity CHECK(maximum_enrollments>0));
CREATE TABLE activity_session(id UUID PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES identity_tenant(id),activity_id UUID NOT NULL REFERENCES activity(id),starts_at TIMESTAMP WITH TIME ZONE NOT NULL,ends_at TIMESTAMP WITH TIME ZONE NOT NULL,location VARCHAR(180),status VARCHAR(20) NOT NULL DEFAULT 'SCHEDULED',CONSTRAINT ck_activity_session_dates CHECK(ends_at>starts_at),CONSTRAINT ck_activity_session_status CHECK(status IN('SCHEDULED','COMPLETED','CANCELLED')));
CREATE TABLE activity_enrollment(id UUID PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES identity_tenant(id),activity_id UUID NOT NULL REFERENCES activity(id),student_id UUID NOT NULL REFERENCES student_profile(id),enrolled_by_kind VARCHAR(20) NOT NULL,enrolled_by_reference_id UUID NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'ENROLLED',enrolled_at TIMESTAMP WITH TIME ZONE NOT NULL,cancelled_at TIMESTAMP WITH TIME ZONE,CONSTRAINT uq_activity_enrollment UNIQUE(tenant_id,activity_id,student_id),CONSTRAINT ck_activity_enrollment_status CHECK(status IN('ENROLLED','CANCELLED')));
CREATE TABLE activity_waiting_list(id UUID PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES identity_tenant(id),activity_id UUID NOT NULL REFERENCES activity(id),student_id UUID NOT NULL REFERENCES student_profile(id),requested_by_portal_account_id UUID REFERENCES admission_portal_account(id),position_number INTEGER NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'WAITING',requested_at TIMESTAMP WITH TIME ZONE NOT NULL,promoted_at TIMESTAMP WITH TIME ZONE,CONSTRAINT uq_activity_waiting UNIQUE(tenant_id,activity_id,student_id),CONSTRAINT ck_waiting_position CHECK(position_number>0),CONSTRAINT ck_waiting_status CHECK(status IN('WAITING','PROMOTED','CANCELLED')));
CREATE TABLE activity_charge(id UUID PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES identity_tenant(id),activity_id UUID NOT NULL REFERENCES activity(id),enrollment_id UUID NOT NULL REFERENCES activity_enrollment(id),student_id UUID NOT NULL REFERENCES student_profile(id),billing_charge_id UUID NOT NULL REFERENCES billing_charge(id),amount NUMERIC(14,2) NOT NULL,charged_on DATE NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT uq_activity_charge_enrollment UNIQUE(tenant_id,enrollment_id),CONSTRAINT ck_activity_charge_amount CHECK(amount>=0));
CREATE INDEX idx_activity_status ON activity(tenant_id,status,category);CREATE INDEX idx_activity_enrollment ON activity_enrollment(tenant_id,activity_id,status);CREATE INDEX idx_activity_waiting ON activity_waiting_list(tenant_id,activity_id,status,position_number);
